import os

FILES = {}

FILES['crawler/merge.py'] = '"""\nMerge raw VedicScriptures responses into data/verses.json and data/links.json\n(Person 3: Anvi).\n\nInput:  one JSON file per verse in data/raw/vedicscriptures/ — exactly what the\n        API returns for /slok/<chapter>/<verse>/ (Antara\'s crawler saves these).\nOutput: data/verses.json  — one clean Verse record per verse (see schemas.py)\n        data/links.json   — verse-to-verse cross-references found in the commentaries\n\nRun from the repo root:\n    python crawler/merge.py\n    python crawler/merge.py --raw some/other/folder     (optional)\n\nNotes for the report:\n- The source has one extra entry per chapter: the closing colophon\n  ("ॐ तत्सदिति ... नाम ... अध्यायः"). It is not a verse, so it is dropped.\n- This edition has 35 verses in chapter 13, so the total is 701, not 700.\n- Links come from Swami Ramsukhdas\'s Hindi commentary ("(गीता 6। 30)" or "(6। 30)")\n  and Prabhupada\'s English purport ("Bg. 18.69"). References to other texts\n  (मानस, श्रीमद्भागवत, Upaniṣads ...) and three-part numbers are ignored.\n"""\n\nimport argparse\nimport glob\nimport json\nimport os\nimport re\nimport sys\nfrom collections import Counter\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom schemas import validate_verse  # noqa: E402\n\nRAW_DIR = os.path.join("data", "raw", "vedicscriptures")\nVERSES_OUT = os.path.join("data", "verses.json")\nLINKS_OUT = os.path.join("data", "links.json")\nSOURCE_URL = "https://vedicscriptures.github.io/slok/{ch}/{v}/"\n\n# (source key in the API response, field, our translation key)\nENGLISH_TRANSLATIONS = [\n    ("siva", "et", "en_sivananda"),\n    ("purohit", "et", "en_purohit"),\n    ("gambir", "et", "en_gambirananda"),\n    ("adi", "et", "en_adidevananda"),\n    ("san", "et", "en_sankaranarayan"),\n    ("prabhu", "et", "en_prabhupada"),\n]\nHINDI_TRANSLATIONS = [\n    ("tej", "ht", "hi_tejomayananda"),\n    ("rams", "ht", "hi_ramsukhdas"),\n]\nCOMMENTARY_EN = ("prabhu", "ec")   # English purport\nCOMMENTARY_HI = ("rams", "hc")     # Hindi commentary (richest in cross-references)\n\nCOLOPHON_START = "ॐ तत्सदिति"\nNO_COMMENT = "did not comment"\n\n# ---------------------------------------------------------------------------\n# Cleaning\n# ---------------------------------------------------------------------------\n\n# "2.47 ", "2.47. ", "।।2.47।। ", "2.47।। " at the start of a translation\nLEADING_NUMBER = re.compile(r"^\\s*(?:।।)?\\s*\\d{1,2}\\.\\d{1,3}\\.?\\s*(?:।।)?\\s*")\n# "||२-४७||" or "||2-47||" at the end of a verse\nTRAILING_MARK = re.compile(r"\\|\\|\\s*[\\d०-९]+\\s*-\\s*[\\d०-९]+\\s*\\|\\|\\s*$")\n\n\ndef clean(text) -> str:\n    """Strip verse-number prefixes, odd spaces and \'did not comment\' placeholders."""\n    if not text or not isinstance(text, str):\n        return ""\n    if NO_COMMENT in text:\n        return ""\n    text = text.replace("\\xa0", " ")\n    text = LEADING_NUMBER.sub("", text, count=1)\n    text = re.sub(r"[ \\t]+", " ", text)\n    return text.strip()\n\n\ndef clean_verse_text(text: str) -> str:\n    """Clean the Sanskrit / transliteration text and drop the closing ||2-47|| mark."""\n    text = (text or "").replace("\\xa0", " ")\n    text = TRAILING_MARK.sub("", text.strip())\n    return re.sub(r"[ \\t]+", " ", text).strip()\n\n\ndef get(raw: dict, key: str, field: str) -> str:\n    part = raw.get(key)\n    return clean(part.get(field)) if isinstance(part, dict) else ""\n\n\n# ---------------------------------------------------------------------------\n# Cross-reference extraction\n# ---------------------------------------------------------------------------\n\nHI_PAREN = re.compile(r"\\(([^()]{0,120})\\)")\nHI_PAIR = re.compile(r"(?<![\\d।])\\s*(\\d{1,2})\\s*।\\s*(\\d{1,3})(?!\\s*।\\s*\\d)")\nHI_THREE_PART = re.compile(r"\\d+\\s*।\\s*\\d+\\s*।\\s*\\d+")\nEN_REF = re.compile(r"(?:Bg\\.|Bhagavad-g[iī]t[aā])\\s*\\(?\\s*(\\d{1,2})\\.(\\d{1,3})(?!\\.\\d)")\n\n\ndef hindi_refs(text: str) -> list[tuple[int, int]]:\n    """Gita references in Ramsukhdas\'s commentary: \'(गीता 6। 30)\' or \'(5। 25 12। 4)\'."""\n    refs = []\n    for match in HI_PAREN.finditer(text or ""):\n        inside = match.group(1).strip()\n        if HI_THREE_PART.search(inside):\n            continue  # e.g. (मानस 1। 140। 5) — another text\n        prefix = re.split(r"\\d", inside, maxsplit=1)[0].strip()\n        if prefix not in ("", "गीता", "गाता"):\n            continue  # another text, e.g. मानस, श्रीमद्भा0, योगदर्शन\n        refs += [(int(c), int(v)) for c, v in HI_PAIR.findall(inside)]\n    return refs\n\n\ndef english_refs(text: str) -> list[tuple[int, int]]:\n    """Gita references in Prabhupada\'s purport: \'Bg. 18.69\' or \'Bhagavad-gītā (4.9)\'."""\n    return [(int(c), int(v)) for c, v in EN_REF.findall(text or "")]\n\n\n# ---------------------------------------------------------------------------\n# Main\n# ---------------------------------------------------------------------------\n\ndef to_verse(raw: dict) -> dict:\n    ch, v = int(raw["chapter"]), int(raw["verse"])\n    translations = {}\n    for key, field, name in ENGLISH_TRANSLATIONS + HINDI_TRANSLATIONS:\n        text = get(raw, key, field)\n        if text:\n            translations[name] = text\n\n    return {\n        "id": f"{ch}.{v}",\n        "chapter": ch,\n        "verse": v,\n        "speaker": clean(raw.get("speaker", "")),\n        "sanskrit": clean_verse_text(raw.get("slok", "")),\n        "transliteration": clean_verse_text(raw.get("transliteration", "")),\n        "translations": translations,\n        "commentary": get(raw, *COMMENTARY_EN),\n        "commentary_hi": get(raw, *COMMENTARY_HI),\n        "source_urls": [SOURCE_URL.format(ch=ch, v=v)],\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--raw", default=RAW_DIR, help="folder with one raw JSON per verse")\n    args = parser.parse_args()\n\n    files = glob.glob(os.path.join(args.raw, "*.json"))\n    if not files:\n        sys.exit(f"No JSON files found in {args.raw}")\n\n    raws = []\n    for path in files:\n        with open(path, encoding="utf-8") as f:\n            raws.append(json.load(f))\n\n    # 1. drop the closing colophon of each chapter\n    real = [r for r in raws if not str(r.get("slok", "")).strip().startswith(COLOPHON_START)]\n    print(f"Read {len(raws)} files, dropped {len(raws) - len(real)} chapter colophons")\n\n    # 2. convert and validate\n    verses = sorted((to_verse(r) for r in real), key=lambda x: (x["chapter"], x["verse"]))\n    bad = 0\n    for verse in verses:\n        problems = validate_verse(verse)\n        if problems:\n            bad += 1\n            print(f"  {verse[\'id\']}: {problems}")\n    valid_ids = {v["id"] for v in verses}\n\n    # 3. extract links (only to verses that exist, never to itself, no duplicates)\n    links, seen = [], set()\n    for raw, verse in zip(sorted(real, key=lambda r: (int(r["chapter"]), int(r["verse"]))), verses):\n        found = [("rams_hi", ref) for ref in hindi_refs(get(raw, *COMMENTARY_HI))]\n        found += [("prabhu_en", ref) for ref in english_refs(get(raw, *COMMENTARY_EN))]\n        for source, (c, v) in found:\n            target = f"{c}.{v}"\n            key = (verse["id"], target)\n            if target in valid_ids and target != verse["id"] and key not in seen:\n                seen.add(key)\n                links.append({"from": verse["id"], "to": target, "source": source})\n\n    # 4. save\n    os.makedirs("data", exist_ok=True)\n    with open(VERSES_OUT, "w", encoding="utf-8") as f:\n        json.dump(verses, f, ensure_ascii=False, indent=2)\n    with open(LINKS_OUT, "w", encoding="utf-8") as f:\n        json.dump(links, f, ensure_ascii=False, indent=2)\n\n    per_chapter = Counter(v["chapter"] for v in verses)\n    linked = len({l["from"] for l in links} | {l["to"] for l in links})\n    print(f"Saved {len(verses)} verses to {VERSES_OUT} ({bad} with problems)")\n    print(f"Verses per chapter: {dict(sorted(per_chapter.items()))}")\n    print(f"Saved {len(links)} links to {LINKS_OUT}, touching {linked} verses")\n    print(f"Links by source: {dict(Counter(l[\'source\'] for l in links))}")\n\n\nif __name__ == "__main__":\n    main()\n'

FILES['generation/llm.py'] = '"""\nShared OpenAI helper (Person 3: Anvi).\n\nEvery LLM call in Saarthi goes through ask() / ask_json(), so the model,\nthe API key and the cache live in one place.\n\nSetup:\n    pip install openai python-dotenv\n    In your .env file (never committed):\n        LLM_API_KEY=sk-...\n        LLM_MODEL=gpt-4o-mini        (optional; change if OpenAI retires this model)\n\nResponses are cached in data/processed/llm_cache.json, so asking the same thing\ntwice costs nothing and evaluation runs are repeatable.\n"""\n\nimport hashlib\nimport json\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nMODEL = os.getenv("LLM_MODEL", "gpt-4o-mini")\nCACHE_PATH = os.path.join("data", "processed", "llm_cache.json")\n\n_client = None\n_cache = None\n\n\ndef _get_client():\n    """Create the OpenAI client the first time it is needed."""\n    global _client\n    if _client is None:\n        from openai import OpenAI\n\n        key = os.getenv("LLM_API_KEY") or os.getenv("OPENAI_API_KEY")\n        if not key:\n            raise RuntimeError("No API key: add LLM_API_KEY=sk-... to your .env file")\n        _client = OpenAI(api_key=key)\n    return _client\n\n\ndef _load_cache() -> dict:\n    global _cache\n    if _cache is None:\n        try:\n            with open(CACHE_PATH, encoding="utf-8") as f:\n                _cache = json.load(f)\n        except (FileNotFoundError, json.JSONDecodeError):\n            _cache = {}\n    return _cache\n\n\ndef _save_cache() -> None:\n    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)\n    with open(CACHE_PATH, "w", encoding="utf-8") as f:\n        json.dump(_cache, f, ensure_ascii=False, indent=1)\n\n\ndef ask(prompt: str, system: str = "", json_mode: bool = False, temperature: float = 0.2) -> str:\n    """Send one prompt to the LLM and return its reply as text (cached)."""\n    cache = _load_cache()\n    key = hashlib.sha256(json.dumps([MODEL, system, prompt, json_mode, temperature]).encode()).hexdigest()\n    if key in cache:\n        return cache[key]\n\n    messages = [{"role": "system", "content": system}] if system else []\n    messages.append({"role": "user", "content": prompt})\n    kwargs = {"model": MODEL, "messages": messages, "temperature": temperature}\n    if json_mode:\n        kwargs["response_format"] = {"type": "json_object"}\n\n    reply = _get_client().chat.completions.create(**kwargs).choices[0].message.content or ""\n    cache[key] = reply\n    _save_cache()\n    return reply\n\n\ndef ask_json(prompt: str, system: str = "", temperature: float = 0.2) -> dict:\n    """Like ask(), but the reply must be a JSON object; returns it as a dict."""\n    reply = ask(prompt, system=system, json_mode=True, temperature=temperature)\n    try:\n        return json.loads(reply)\n    except json.JSONDecodeError:\n        return {}\n'

FILES['query/rewrite.py'] = '"""\nLLM query rewriting (Person 3: Anvi).\n\nrewrite() turns an everyday question into the underlying Gita concepts, e.g.\n"I studied hard but still failed my exam" -> ["attachment to results",\n"equanimity in success and failure", "doing one\'s duty"].\nThese concepts are added to the search query to bridge the vocabulary gap\nbetween modern questions and the Gita\'s language (HyDE-style query rewriting).\n"""\n\nimport os\nimport sys\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom generation.llm import ask_json  # noqa: E402\n\nSYSTEM = (\n    "You help a search engine over the Bhagavad Gita. Given a modern, everyday "\n    "question, list the philosophical concepts from the Gita that the question is "\n    "really about. Use plain English phrases of 1-5 words that are likely to appear "\n    "in English translations of the Gita (e.g. \'fruits of action\', \'duty\', "\n    "\'steady mind\', \'attachment\', \'desire and anger\', \'the self\'). "\n    "Do not quote verses and do not give advice."\n)\n\nPROMPT = (\n    \'Question: "{question}"\\n\\n\'\n    \'Reply as JSON: {{"concepts": ["...", "..."]}} with 3 to 5 concepts.\'\n)\n\n\ndef rewrite(query_en: str) -> list[str]:\n    """Return 3-5 Gita concepts for an English question (empty list on failure)."""\n    if not query_en.strip():\n        return []\n    reply = ask_json(PROMPT.format(question=query_en.strip()), system=SYSTEM)\n    concepts = reply.get("concepts", [])\n    return [str(c).strip() for c in concepts if str(c).strip()][:5]\n\n\ndef expanded_query(query_en: str) -> str:\n    """The question plus its concepts, ready to pass to BM25 or dense search."""\n    concepts = rewrite(query_en)\n    return query_en if not concepts else f"{query_en} {\' \'.join(concepts)}"\n\n\nif __name__ == "__main__":\n    q = "I studied really hard but still failed my exam. How do I stop feeling like a failure?"\n    print(rewrite(q))\n    print(expanded_query(q))\n'

FILES['query/language.py'] = '"""\nLanguage handling for user questions (Person 3: Anvi).\n\nprocess_query() works out whether a question is English, Hindi or Hinglish,\nand returns a Devanagari Hindi version and an English version, so both the\nEnglish and the Hindi indexes can be searched.\n\n- Language detection: rule-based (Devanagari characters -> Hindi; Roman letters\n  with common Hindi words -> Hinglish; otherwise English).\n- Transliteration + translation: one LLM call (cached). We use the LLM rather\n  than IndicTrans2 / IndicXlit because those models are large and hard to install\n  on Windows, and the LLM handles Hinglish\'s loose spelling well.\n  (Mention this choice in the report.)\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom generation.llm import ask_json  # noqa: E402\n\n# common Hindi words typed in Roman letters, used to spot Hinglish\nHINGLISH_MARKERS = {\n    "hai", "hain", "kya", "kaise", "kyun", "kyon", "mera", "meri", "mere",\n    "nahi", "nahin", "main", "mein", "ho", "gaya", "gayi", "karu", "karun",\n    "karoon", "kar", "raha", "rahi", "tha", "thi", "aur", "bhi", "ko", "se",\n    "ki", "ka", "ke", "par", "lekin", "kuch", "bahut", "accha", "acha", "hoon",\n    "hun", "mujhe", "mujhko", "apne", "apna", "sab", "jab", "toh", "kyunki",\n}\n\nDEVANAGARI = re.compile(r"[ऀ-ॿ]")\n\nSYSTEM = (\n    "You convert user questions between English, Hindi (Devanagari script) and "\n    "Hinglish (Hindi typed in Roman letters, often mixed with English words). "\n    "Keep the meaning exactly; do not answer the question or add anything."\n)\n\nPROMPT = (\n    \'The question below is written in {lang_name}.\\n\'\n    \'Question: "{text}"\\n\\n\'\n    \'Reply as JSON: {{"hindi": "<the question in natural Hindi, Devanagari script>", \'\n    \'"english": "<the question in natural English>"}}\'\n)\n\nLANG_NAMES = {"en": "English", "hi": "Hindi", "hinglish": "Hinglish"}\n\n\ndef detect_language(text: str) -> str:\n    """Return "hi" (Devanagari), "hinglish" (Roman-script Hindi) or "en"."""\n    if DEVANAGARI.search(text):\n        return "hi"\n\n    words = re.findall(r"[a-zA-Z]+", text.lower())\n    if not words:\n        return "en"\n\n    hindi_like = sum(1 for w in words if w in HINGLISH_MARKERS)\n    # two or more Hindi marker words, or at least a fifth of the words\n    if hindi_like >= 2 or hindi_like / len(words) >= 0.2:\n        return "hinglish"\n    return "en"\n\n\ndef process_query(raw: str) -> dict:\n    """Turn a raw question in any language into Hindi and English versions.\n\n    Returns:\n        {"lang": "en" | "hi" | "hinglish", "hindi": str, "english": str, "original": str}\n    If the LLM call fails, the original text is used for both versions.\n    """\n    raw = raw.strip()\n    lang = detect_language(raw)\n\n    try:\n        reply = ask_json(PROMPT.format(lang_name=LANG_NAMES[lang], text=raw), system=SYSTEM)\n    except Exception as err:  # no key, no internet, API error\n        print(f"[language] translation failed, using original text: {err}")\n        reply = {}\n\n    hindi = (reply.get("hindi") or "").strip() or raw\n    english = (reply.get("english") or "").strip() or raw\n    if lang == "en":\n        english = raw  # never change an English question\n    if lang == "hi":\n        hindi = raw\n\n    return {"lang": lang, "hindi": hindi, "english": english, "original": raw}\n\n\nif __name__ == "__main__":\n    for q in [\n        "I failed my exam, how do I cope?",\n        "exam mein fail ho gaya, kya karun",\n        "मैं परीक्षा में फेल हो गया, क्या करूँ?",\n    ]:\n        print(process_query(q))\n'

FILES['indexing/embeddings.py'] = '"""\nMultilingual meaning search (Person 3: Anvi).\n\nbuild_embeddings() turns every translation of every verse into a vector.\nsearch_dense() embeds the question and finds the verses whose translations are\nclosest in meaning (cosine similarity), in any language: a Hindi question can\nmatch an English translation and the other way round.\n\nModel: intfloat/multilingual-e5-base (about 1.1 GB, downloaded once on first use).\ne5 models expect "query: " in front of questions and "passage: " in front of documents.\n\nUsage (from the repo root):\n    python indexing/embeddings.py            # builds the index (a few minutes on CPU)\n    python indexing/embeddings.py "how do I deal with failure?"\n"""\n\nimport json\nimport os\nimport sys\n\nimport numpy as np\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom schemas import SearchResult, make_result  # noqa: E402\n\nMODEL_NAME = "intfloat/multilingual-e5-base"\nVERSES_PATH = os.path.join("data", "verses.json")\nSAMPLE_PATH = os.path.join("data", "sample_verses.json")\nVECTORS_PATH = os.path.join("data", "processed", "embeddings.npy")\nMETA_PATH = os.path.join("data", "processed", "embeddings_meta.json")\n\n_model = None\n_vectors = None\n_meta = None\n\n\ndef get_model():\n    """Load the embedding model once (first call downloads it)."""\n    global _model\n    if _model is None:\n        from sentence_transformers import SentenceTransformer\n\n        _model = SentenceTransformer(MODEL_NAME)\n    return _model\n\n\ndef load_verses() -> list[dict]:\n    """Full verses.json if it exists, otherwise the 50-verse sample."""\n    path = VERSES_PATH if os.path.exists(VERSES_PATH) else SAMPLE_PATH\n    with open(path, encoding="utf-8") as f:\n        return json.load(f)\n\n\ndef build_embeddings(verses: list[dict] | None = None, batch_size: int = 32) -> None:\n    """Embed every translation of every verse and save vectors + metadata."""\n    verses = verses if verses is not None else load_verses()\n\n    texts, meta = [], []\n    for verse in verses:\n        for key, text in verse["translations"].items():\n            if text.strip():\n                texts.append("passage: " + text.strip())\n                meta.append({"id": verse["id"], "translation": key, "lang": key.split("_")[0]})\n\n    print(f"Embedding {len(texts)} translations of {len(verses)} verses with {MODEL_NAME} ...")\n    vectors = get_model().encode(\n        texts, batch_size=batch_size, normalize_embeddings=True, show_progress_bar=True\n    )\n\n    os.makedirs(os.path.dirname(VECTORS_PATH), exist_ok=True)\n    np.save(VECTORS_PATH, vectors.astype(np.float32))\n    with open(META_PATH, "w", encoding="utf-8") as f:\n        json.dump(meta, f, ensure_ascii=False)\n    print(f"Saved {vectors.shape} vectors to {VECTORS_PATH}")\n\n\ndef _load_index():\n    global _vectors, _meta\n    if _vectors is None:\n        if not os.path.exists(VECTORS_PATH):\n            raise FileNotFoundError("No embeddings yet: run  python indexing/embeddings.py")\n        _vectors = np.load(VECTORS_PATH)\n        with open(META_PATH, encoding="utf-8") as f:\n            _meta = json.load(f)\n    return _vectors, _meta\n\n\ndef search_dense(query: str, k: int = 20, lang: str | None = None) -> list[SearchResult]:\n    """Return the k verses closest in meaning to the query, best first.\n\n    Each verse scores the similarity of its best-matching translation.\n    lang: None = search all translations; "en" or "hi" = only that language\n          (used in the multilingual experiment).\n    """\n    vectors, meta = _load_index()\n    q = get_model().encode(["query: " + query.strip()], normalize_embeddings=True)[0]\n    sims = vectors @ q  # cosine similarity, since all vectors are normalised\n\n    best: dict[str, float] = {}\n    for sim, m in zip(sims, meta):\n        if lang and m["lang"] != lang:\n            continue\n        if sim > best.get(m["id"], -1.0):\n            best[m["id"]] = float(sim)\n\n    ranked = sorted(best.items(), key=lambda item: item[1], reverse=True)[:k]\n    return [make_result(verse_id, score, "dense") for verse_id, score in ranked]\n\n\nif __name__ == "__main__":\n    if len(sys.argv) > 1:\n        for r in search_dense(" ".join(sys.argv[1:]), k=5):\n            print(r)\n    else:\n        build_embeddings()\n'

FILES['generation/fact_check.py'] = '"""\nNLI fact-checker (Person 3: Anvi).\n\nverify() checks every sentence of an explanation against the verse(s) it cites.\nA Natural Language Inference (NLI) model reads (premise = verse translation,\nhypothesis = sentence) and predicts entailment / neutral / contradiction.\nA sentence counts as supported if P(entailment) >= THRESHOLD for at least one\ncited verse.\n\nModel: MoritzLaurer/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7\n(multilingual, about 1.1 GB, downloaded once on first use; needs `sentencepiece`).\n\nPipeline order: explain in English -> verify -> translate for the user.\nSentences with no citation (e.g. a short intro) get supported = None: they are\nnot claims about a verse, so they are neither ticked nor removed.\n"""\n\nimport re\n\nMODEL_NAME = "MoritzLaurer/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7"\nTHRESHOLD = 0.5  # tune on a few hand-checked answers; report the value used\n\nCITATION = re.compile(r"\\[(\\d{1,2}\\.\\d{1,3})\\]")\nDEVANAGARI = re.compile(r"[ऀ-ॿ]")\n\n_tokenizer = None\n_model = None\n\n\ndef split_sentences(text: str) -> list[str]:\n    """Split text into sentences on . ! ? and the Hindi full stop ।"""\n    parts = re.split(r"(?<=[.!?।])\\s+", text.strip())\n    return [p.strip() for p in parts if p.strip()]\n\n\ndef _load_model():\n    global _tokenizer, _model\n    if _model is None:\n        from transformers import AutoModelForSequenceClassification, AutoTokenizer\n\n        _tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)\n        _model = AutoModelForSequenceClassification.from_pretrained(MODEL_NAME)\n        _model.eval()\n    return _tokenizer, _model\n\n\ndef entailment_prob(premise: str, hypothesis: str) -> float:\n    """Probability that the premise supports (entails) the hypothesis."""\n    import torch\n\n    tokenizer, model = _load_model()\n    inputs = tokenizer(premise, hypothesis, truncation=True, max_length=512, return_tensors="pt")\n    with torch.no_grad():\n        probs = torch.softmax(model(**inputs).logits[0], dim=-1)\n    labels = {name.lower(): i for i, name in model.config.id2label.items()}\n    return float(probs[labels["entailment"]])\n\n\ndef premise_for(verse: dict, sentence: str) -> str:\n    """The verse text to check against, in the same script as the sentence (two translations)."""\n    prefix = "hi_" if DEVANAGARI.search(sentence) else "en_"\n    texts = [t for k, t in verse.get("translations", {}).items() if k.startswith(prefix) and t]\n    if not texts:  # fall back to any translation\n        texts = [t for t in verse.get("translations", {}).values() if t]\n    return " ".join(texts[:2])\n\n\ndef verify(explanation: str, verses: list[dict], threshold: float = THRESHOLD) -> list[dict]:\n    """Return one entry per sentence:\n        {"sentence", "verse_ids", "score", "supported"}\n    supported is True / False for sentences that cite a verse, None for the rest.\n    """\n    by_id = {v["id"]: v for v in verses}\n    checks = []\n    for sentence in split_sentences(explanation):\n        cited = [vid for vid in CITATION.findall(sentence)]\n        claim = CITATION.sub("", sentence).strip()\n\n        if not cited:\n            checks.append({"sentence": sentence, "verse_ids": [], "score": None, "supported": None})\n            continue\n\n        known = [by_id[vid] for vid in cited if vid in by_id]\n        if not known:  # cites a verse that was not retrieved: cannot be supported\n            checks.append({"sentence": sentence, "verse_ids": cited, "score": 0.0, "supported": False})\n            continue\n\n        score = max(entailment_prob(premise_for(v, claim), claim) for v in known)\n        checks.append({\n            "sentence": sentence,\n            "verse_ids": cited,\n            "score": round(score, 3),\n            "supported": score >= threshold,\n        })\n    return checks\n\n\ndef keep_supported(checks: list[dict]) -> str:\n    """Rebuild the explanation without the unsupported sentences."""\n    return " ".join(c["sentence"] for c in checks if c["supported"] is not False)\n\n\nif __name__ == "__main__":\n    verse = {"id": "2.47", "translations": {\n        "en_gambirananda": "Your right is for action alone, never for the results.",\n    }}\n    text = ("Here is what the Gita says. Focus on doing your work, not on the outcome [2.47]. "\n            "The Gita promises that hard work always brings success [2.47].")\n    for c in verify(text, [verse]):\n        print(c)\n'

FILES['generation/rag.py'] = '"""\nRAG explanation (Person 3: Anvi).\n\nexplain() gives the LLM the user\'s question plus the top retrieved verses and asks\nfor a short explanation that uses ONLY those verses, citing [chapter.verse] after\nevery claim. The explanation is written in English so the fact-checker can verify\nit; translate_answer() then converts it to Hindi or Hinglish for the user.\n\nSafety: if the question suggests serious distress, a fixed support note is added\n(Tele-MANAS, the Government of India\'s free mental-health helpline: 14416).\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom generation.llm import ask  # noqa: E402\n\nCITATION = re.compile(r"\\[(\\d{1,2}\\.\\d{1,3})\\]")\n\nSYSTEM = (\n    "You explain verses of the Bhagavad Gita to someone asking an everyday life question. "\n    "Rules:\\n"\n    "1. Use ONLY the verses provided. Never quote or mention any other verse.\\n"\n    "2. Put the verse id in square brackets, like [2.47], at the end of every sentence "\n    "that says what a verse teaches.\\n"\n    "3. Only say what the verse text actually says; do not add promises, outcomes or "\n    "interpretations the text does not state.\\n"\n    "4. Be warm, simple and non-preachy. No commands like \'you must\'. Present it as what "\n    "the Gita suggests, not as absolute truth.\\n"\n    "5. 4 to 7 sentences, plain English, no headings or lists."\n)\n\nPROMPT = "Question: {question}\\n\\nVerses:\\n{verses}\\n\\nWrite the explanation."\n\nDISTRESS_WORDS = [\n    "suicide", "kill myself", "end my life", "want to die", "self harm", "self-harm",\n    "no reason to live", "hurt myself", "marna chahta", "marna chahti", "jeena nahi",\n    "आत्महत्या", "मरना चाहता", "मरना चाहती", "जीना नहीं",\n]\nSAFETY_NOTE = (\n    "If you are going through something very heavy right now, please talk to someone you "\n    "trust or call Tele-MANAS on 14416 (free, 24x7, in many Indian languages). "\n    "You don\'t have to handle this alone."\n)\n\nTRANSLATIONS_PER_VERSE = ["en_gambirananda", "en_prabhupada", "en_sivananda", "en_adidevananda"]\n\n\ndef format_verses(verses: list[dict]) -> str:\n    """Each verse as \'[2.47] translation one / translation two\'."""\n    lines = []\n    for verse in verses:\n        texts = [verse["translations"][k] for k in TRANSLATIONS_PER_VERSE if verse["translations"].get(k)]\n        if not texts:\n            texts = [t for k, t in verse["translations"].items() if k.startswith("en_")]\n        lines.append(f"[{verse[\'id\']}] " + " / ".join(texts[:2]))\n    return "\\n".join(lines)\n\n\ndef needs_safety_note(question: str) -> bool:\n    q = question.lower()\n    return any(word in q for word in DISTRESS_WORDS)\n\n\ndef explain(question: str, verses: list[dict]) -> dict:\n    """Write an English explanation that uses only the given verses.\n\n    Args:\n        question: the user\'s question (English version from process_query)\n        verses: top 3-5 verse records (schemas.Verse)\n\n    Returns:\n        {"text": str, "citations": ["2.47", ...], "safety_note": str | None}\n    """\n    if not verses:\n        return {"text": "I couldn\'t find verses that clearly answer this question.",\n                "citations": [], "safety_note": None}\n\n    text = ask(PROMPT.format(question=question, verses=format_verses(verses)),\n               system=SYSTEM, temperature=0.3).strip()\n\n    allowed = {v["id"] for v in verses}\n    citations = [vid for vid in dict.fromkeys(CITATION.findall(text)) if vid in allowed]\n    return {\n        "text": text,\n        "citations": citations,\n        "safety_note": SAFETY_NOTE if needs_safety_note(question) else None,\n    }\n\n\nif __name__ == "__main__":\n    import json\n\n    with open(os.path.join("data", "verses.json"), encoding="utf-8") as f:\n        by_id = {v["id"]: v for v in json.load(f)}\n    answer = explain("I studied hard but still failed my exam. How do I cope?",\n                     [by_id["2.47"], by_id["2.48"], by_id["2.38"]])\n    print(answer)\n'

FILES['generation/translate.py'] = '"""\nAnswer translation (Person 3: Anvi).\n\ntranslate_answer() converts the verified English explanation into Hindi\n(Devanagari) or Hinglish (Hindi in Roman letters), keeping every [2.47]\ncitation exactly as it is so the answer panel can still link to the verses.\n"""\n\nimport os\nimport re\nimport sys\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom generation.llm import ask  # noqa: E402\n\nCITATION = re.compile(r"\\[(\\d{1,2}\\.\\d{1,3})\\]")\n\nTARGETS = {\n    "hi": "natural, simple Hindi in Devanagari script",\n    "hinglish": "Hinglish: casual Hindi written in Roman letters, the way people text in India",\n}\n\nSYSTEM = (\n    "You translate short explanations about the Bhagavad Gita. Keep the meaning and tone "\n    "exactly, add nothing, and keep every citation like [2.47] unchanged and in the same "\n    "place in its sentence. Reply with the translation only."\n)\n\n\ndef translate_answer(text: str, target_lang: str) -> str:\n    """Translate an English explanation into "en", "hi" or "hinglish"."""\n    if target_lang not in {"en", "hi", "hinglish"}:\n        raise ValueError(f"unknown language: {target_lang}")\n    if target_lang == "en" or not text.strip():\n        return text\n\n    translated = ask(f"Translate into {TARGETS[target_lang]}:\\n\\n{text}", system=SYSTEM).strip()\n\n    # safety net: if citations went missing, fall back to the English text\n    if set(CITATION.findall(translated)) != set(CITATION.findall(text)):\n        print("[translate] citations changed during translation; showing English instead")\n        return text\n    return translated\n\n\nif __name__ == "__main__":\n    english = "The Gita suggests focusing on your effort rather than the result [2.47]."\n    print(translate_answer(english, "hi"))\n    print(translate_answer(english, "hinglish"))\n'

NEW_REQUIREMENTS = ["openai", "sentencepiece", "protobuf"]


def main():
    for path, content in FILES.items():
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(content)
        print(f"updated: {path}")

    req = open("requirements.txt", encoding="utf-8").read().split() if os.path.exists("requirements.txt") else []
    missing = [p for p in NEW_REQUIREMENTS if p not in req]
    if missing:
        with open("requirements.txt", "a", encoding="utf-8") as fh:
            fh.write("\n" + "\n".join(missing) + "\n")
        print(f"added to requirements.txt: {missing}")

    env = open(".env.example", encoding="utf-8").read() if os.path.exists(".env.example") else ""
    if "LLM_MODEL" not in env:
        with open(".env.example", "a", encoding="utf-8") as fh:
            fh.write("\nLLM_MODEL=gpt-4o-mini\n")
        print("added LLM_MODEL to .env.example")


if __name__ == "__main__":
    main()
